    /// A `Style` node (tag 1, interned).
    #[derive(Clone, Copy)]
    pub struct Style<'a> {
        raw: Raw<'a>,
        at: usize,
        index: u32,
    }

    impl<'a> Style<'a> {
        pub const TAG: u16 = 1;

        fn from_raw(raw: Raw<'a>, index: u32) -> Self {
            Style { raw, at: raw.node_at(index), index }
        }

        /// The node's index in the file.
        pub fn index(&self) -> u32 {
            self.index
        }
        pub fn face(&self) -> &'a str {
            self.raw.string(self.raw.u32(self.at + 4))
        }
        pub fn face_id(&self) -> u32 {
            self.raw.u32(self.at + 4)
        }
        pub fn flags(&self) -> u32 {
            let raw = self.raw;
            raw.u32(self.at + 8)
        }
        pub fn align(&self) -> u8 {
            let raw = self.raw;
            raw.u8(self.at + 12)
        }
        pub fn size_bits(&self) -> u64 {
            let raw = self.raw;
            raw.u64(self.at + 13)
        }
        pub fn parent(&self) -> Option<Style<'a>> {
            let r = self.raw.u32(self.at + 21);
            if r == NONE { None } else { Some(Style::from_raw(self.raw, r)) }
        }
    }

